CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN new.updated_at = now(); return new; END; $$;
CREATE OR REPLACE FUNCTION get_setting_numeric(p_key text) RETURNS numeric LANGUAGE sql STABLE SET search_path = public AS $$ SELECT (value #>> '{}')::numeric FROM system_settings WHERE key = p_key; $$;
CREATE OR REPLACE FUNCTION get_setting_bool(p_key text) RETURNS boolean LANGUAGE sql STABLE SET search_path = public AS $$ SELECT (value #>> '{}')::boolean FROM system_settings WHERE key = p_key; $$;

CREATE OR REPLACE FUNCTION claim_ride(p_ride_id uuid, p_provider_id uuid, p_vehicle_id uuid) RETURNS ride_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_ride ride_requests; BEGIN IF NOT exists (SELECT 1 FROM vehicles WHERE id = p_vehicle_id AND provider_id = p_provider_id AND is_available = true) THEN RAISE EXCEPTION 'VEHICLE_NOT_ELIGIBLE'; END IF; IF NOT exists (SELECT 1 FROM provider_profiles WHERE id = p_provider_id AND provider_type = 'VEHICLE_PROVIDER' AND status = 'APPROVED') THEN RAISE EXCEPTION 'PROVIDER_NOT_ELIGIBLE'; END IF; UPDATE ride_requests SET status = 'CLAIMED', claimed_by_provider_id = p_provider_id, claimed_vehicle_id = p_vehicle_id, claimed_at = now(), updated_at = now() WHERE id = p_ride_id AND status = 'REQUESTED' RETURNING * INTO v_ride; IF v_ride.id IS NULL THEN RAISE EXCEPTION 'RIDE_ALREADY_TAKEN'; END IF; INSERT INTO ride_status_history (ride_request_id, from_status, to_status, changed_by) VALUES (p_ride_id, 'REQUESTED', 'CLAIMED', auth.uid()); INSERT INTO audit_logs (actor_id, event_type, entity_type, entity_id, metadata) VALUES (auth.uid(), 'RIDE_CLAIMED', 'ride_requests', p_ride_id, jsonb_build_object('provider_id', p_provider_id, 'vehicle_id', p_vehicle_id)); RETURN v_ride; END; $$;

CREATE OR REPLACE FUNCTION deduct_transaction_fee(p_provider_id uuid, p_order_id uuid, p_ride_id uuid, p_gross_amount numeric, p_idempotency_key text) RETURNS wallet_transactions LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_wallet wallets; v_fee numeric := get_setting_numeric('transaction_fee'); v_allow boolean := get_setting_bool('allow_negative_wallet'); v_txn wallet_transactions; v_existing wallet_transactions; BEGIN SELECT * INTO v_existing FROM wallet_transactions WHERE idempotency_key = p_idempotency_key; IF v_existing.id IS NOT NULL THEN RETURN v_existing; END IF; SELECT * INTO v_wallet FROM wallets WHERE provider_id = p_provider_id FOR UPDATE; IF v_wallet.id IS NULL THEN RAISE EXCEPTION 'WALLET_NOT_FOUND'; END IF; IF NOT v_allow AND (v_wallet.balance - v_fee) < 0 THEN INSERT INTO wallet_transactions (wallet_id, provider_id, order_id, ride_request_id, transaction_type, gross_amount, platform_fee, net_amount, balance_after, status, idempotency_key) VALUES (v_wallet.id, p_provider_id, p_order_id, p_ride_id, 'TRANSACTION_FEE', p_gross_amount, v_fee, p_gross_amount - v_fee, v_wallet.balance, 'FAILED', p_idempotency_key) RETURNING * INTO v_txn; INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'WALLET_EMPTY', 'Wallet balance too low', 'Transaction fee could not be deducted' FROM provider_profiles WHERE id = p_provider_id; RAISE EXCEPTION 'INSUFFICIENT_WALLET_BALANCE'; END IF; UPDATE wallets SET balance = balance - v_fee, updated_at = now() WHERE id = v_wallet.id RETURNING * INTO v_wallet; INSERT INTO wallet_transactions (wallet_id, provider_id, order_id, ride_request_id, transaction_type, gross_amount, platform_fee, net_amount, balance_after, status, idempotency_key) VALUES (v_wallet.id, p_provider_id, p_order_id, p_ride_id, 'TRANSACTION_FEE', p_gross_amount, v_fee, p_gross_amount - v_fee, v_wallet.balance, 'COMPLETED', p_idempotency_key) RETURNING * INTO v_txn; INSERT INTO audit_logs (event_type, entity_type, entity_id, metadata) VALUES ('TRANSACTION_FEE_DEDUCTED', 'wallets', v_wallet.id, jsonb_build_object('provider_id', p_provider_id, 'fee', v_fee, 'balance_after', v_wallet.balance)); INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'TRANSACTION_FEE_DEDUCTED', 'Platform fee deducted', v_fee::text || ' Birr deducted' FROM provider_profiles WHERE id = p_provider_id; IF v_wallet.balance <= get_setting_numeric('low_wallet_threshold') THEN INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'WALLET_LOW', 'Wallet balance low', 'Your wallet balance is low' FROM provider_profiles WHERE id = p_provider_id; END IF; RETURN v_txn; END; $$;

CREATE OR REPLACE FUNCTION deduct_subscription_fee(p_provider_id uuid, p_period text) RETURNS wallet_transactions LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_wallet wallets; v_fee numeric := get_setting_numeric('monthly_subscription_fee'); v_key text := 'sub:' || p_provider_id::text || ':' || p_period; v_existing wallet_transactions; v_txn wallet_transactions; BEGIN SELECT * INTO v_existing FROM wallet_transactions WHERE idempotency_key = v_key; IF v_existing.id IS NOT NULL THEN RETURN v_existing; END IF; SELECT * INTO v_wallet FROM wallets WHERE provider_id = p_provider_id FOR UPDATE; IF v_wallet.id IS NULL THEN RAISE EXCEPTION 'WALLET_NOT_FOUND'; END IF; UPDATE wallets SET balance = balance - v_fee, updated_at = now() WHERE id = v_wallet.id RETURNING * INTO v_wallet; INSERT INTO wallet_transactions (wallet_id, provider_id, transaction_type, gross_amount, platform_fee, net_amount, balance_after, status, idempotency_key) VALUES (v_wallet.id, p_provider_id, 'SUBSCRIPTION_FEE', v_fee, v_fee, 0, v_wallet.balance, 'COMPLETED', v_key) RETURNING * INTO v_txn; UPDATE subscriptions SET last_charged_at = now(), next_due_date = next_due_date + interval '1 month', status = 'ACTIVE' WHERE provider_id = p_provider_id; INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'SUBSCRIPTION_DUE', 'Subscription charged', v_fee::text || ' Birr deducted' FROM provider_profiles WHERE id = p_provider_id; RETURN v_txn; END; $$;

CREATE OR REPLACE FUNCTION transition_order_status(p_order_id uuid, p_new_status order_status, p_actor uuid, p_note text DEFAULT null) RETURNS orders LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_order orders; v_old order_status; v_valid boolean := false; v_actor_is_provider boolean := false; v_actor_is_admin boolean := false; BEGIN SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE; IF v_order.id IS NULL THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF; v_old := v_order.status; SELECT exists (SELECT 1 FROM user_roles WHERE user_id = p_actor AND role = 'ADMIN') INTO v_actor_is_admin; SELECT exists (SELECT 1 FROM provider_profiles WHERE id = v_order.provider_id AND user_id = p_actor) INTO v_actor_is_provider; v_valid := case v_old when 'CREATED' then p_new_status in ('PENDING_PROVIDER','CANCELLED') AND (v_order.user_id = p_actor OR v_actor_is_admin) when 'PENDING_PROVIDER' then (p_new_status in ('ACCEPTED','REJECTED') AND (v_actor_is_provider OR v_actor_is_admin)) OR (p_new_status = 'CANCELLED' AND (v_order.user_id = p_actor OR v_actor_is_admin)) when 'ACCEPTED' then (p_new_status = 'PAYMENT_PENDING' AND (v_actor_is_provider OR v_actor_is_admin)) OR (p_new_status = 'CANCELLED' AND (v_order.user_id = p_actor OR v_actor_is_admin)) when 'PAYMENT_PENDING' then (p_new_status = 'PAYMENT_VERIFICATION' AND v_order.user_id = p_actor) OR (p_new_status = 'CANCELLED' AND v_actor_is_admin) when 'PAYMENT_VERIFICATION' then p_new_status in ('APPROVED','REJECTED') AND v_actor_is_admin when 'APPROVED' then (p_new_status = 'STARTED' AND (v_actor_is_provider OR v_actor_is_admin)) OR (p_new_status = 'CANCELLED' AND (v_order.user_id = p_actor OR v_actor_is_admin)) when 'STARTED' then (p_new_status = 'COMPLETED' AND (v_actor_is_provider OR v_actor_is_admin)) OR (p_new_status in ('DISPUTED','CANCELLED') AND (v_order.user_id = p_actor OR v_actor_is_admin)) when 'COMPLETED' then p_new_status in ('DISPUTED','REFUNDED') AND (v_order.user_id = p_actor OR v_actor_is_admin) when 'DISPUTED' then p_new_status in ('REFUNDED','COMPLETED') AND v_actor_is_admin else false end; IF NOT v_valid THEN RAISE EXCEPTION 'INVALID_TRANSITION_%_TO_%_FOR_ACTOR', v_old, p_new_status; END IF; IF p_new_status = 'APPROVED' AND v_order.requires_payment_proof THEN IF NOT exists (SELECT 1 FROM payment_proofs WHERE order_id = p_order_id AND verification_status = 'VERIFIED') THEN RAISE EXCEPTION 'PAYMENT_PROOF_REQUIRED'; END IF; END IF; UPDATE orders SET status = p_new_status, updated_at = now() WHERE id = p_order_id RETURNING * INTO v_order; INSERT INTO order_status_history (order_id, from_status, to_status, changed_by, note) VALUES (p_order_id, v_old, p_new_status, p_actor, p_note); IF p_new_status = 'STARTED' THEN PERFORM deduct_transaction_fee(v_order.provider_id, p_order_id, null, v_order.total_amount, 'order:' || p_order_id::text); END IF; RETURN v_order; END; $$;

CREATE OR REPLACE FUNCTION transition_ride_status(p_ride_id uuid, p_new_status ride_status, p_actor uuid) RETURNS ride_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_ride ride_requests; v_old ride_status; v_actor_is_admin boolean := false; v_actor_is_claiming_provider boolean := false; BEGIN SELECT * INTO v_ride FROM ride_requests WHERE id = p_ride_id FOR UPDATE; IF v_ride.id IS NULL THEN RAISE EXCEPTION 'RIDE_NOT_FOUND'; END IF; v_old := v_ride.status; IF v_old = 'CANCELLED' OR v_old = 'COMPLETED' THEN RAISE EXCEPTION 'RIDE_ALREADY_TERMINAL'; END IF; SELECT exists (SELECT 1 FROM user_roles WHERE user_id = p_actor AND role = 'ADMIN') INTO v_actor_is_admin; IF v_ride.claimed_by_provider_id IS NOT NULL THEN SELECT exists (SELECT 1 FROM provider_profiles WHERE id = v_ride.claimed_by_provider_id AND user_id = p_actor) INTO v_actor_is_claiming_provider; END IF; CASE v_old WHEN 'REQUESTED' THEN IF p_new_status != 'CANCELLED' THEN RAISE EXCEPTION 'USE_CLAIM_RIDE'; END IF; IF v_ride.user_id != p_actor AND NOT v_actor_is_admin THEN RAISE EXCEPTION 'ONLY_RIDER_OR_ADMIN'; END IF; WHEN 'CLAIMED' THEN IF p_new_status = 'CANCELLED' THEN IF v_ride.user_id != p_actor AND NOT v_actor_is_admin THEN RAISE EXCEPTION 'ONLY_RIDER_OR_ADMIN'; END IF; ELSIF NOT v_actor_is_claiming_provider AND NOT v_actor_is_admin THEN RAISE EXCEPTION 'ONLY_CLAIMING_PROVIDER_OR_ADMIN'; END IF; WHEN 'DRIVER_ARRIVING' THEN IF p_new_status = 'CANCELLED' THEN IF v_ride.user_id != p_actor AND NOT v_actor_is_admin THEN RAISE EXCEPTION 'ONLY_RIDER_OR_ADMIN'; END IF; ELSIF NOT v_actor_is_claiming_provider AND NOT v_actor_is_admin THEN RAISE EXCEPTION 'ONLY_CLAIMING_PROVIDER_OR_ADMIN'; END IF; WHEN 'STARTED' THEN IF p_new_status = 'COMPLETED' THEN IF NOT v_actor_is_claiming_provider AND NOT v_actor_is_admin THEN RAISE EXCEPTION 'ONLY_CLAIMING_PROVIDER_OR_ADMIN'; END IF; ELSIF p_new_status = 'CANCELLED' THEN IF v_ride.user_id != p_actor AND NOT v_actor_is_admin THEN RAISE EXCEPTION 'ONLY_RIDER_OR_ADMIN'; END IF; END IF; ELSE RAISE EXCEPTION 'UNEXPECTED_STATUS_%', v_old; END CASE; UPDATE ride_requests SET status = p_new_status, updated_at = now() WHERE id = p_ride_id RETURNING * INTO v_ride; INSERT INTO ride_status_history (ride_request_id, from_status, to_status, changed_by) VALUES (p_ride_id, v_old, p_new_status, p_actor); IF p_new_status = 'COMPLETED' THEN PERFORM deduct_transaction_fee(v_ride.claimed_by_provider_id, null, p_ride_id, coalesce(v_ride.fare_estimate, 0), 'ride:' || p_ride_id::text); END IF; RETURN v_ride; END; $$;

CREATE OR REPLACE FUNCTION approve_provider(p_provider_id uuid, p_admin_id uuid) RETURNS provider_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_provider provider_profiles; v_is_admin boolean; BEGIN SELECT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') INTO v_is_admin; IF NOT v_is_admin THEN RAISE EXCEPTION 'ONLY_ADMINISTRATORS_CAN_APPROVE'; END IF; IF exists (SELECT 1 FROM provider_profiles WHERE id = p_provider_id AND user_id = p_admin_id) THEN RAISE EXCEPTION 'CANNOT_APPROVE_OWN_ACCOUNT'; END IF; UPDATE provider_profiles SET status = 'APPROVED', updated_at = now() WHERE id = p_provider_id RETURNING * INTO v_provider; IF v_provider.id IS NULL THEN RAISE EXCEPTION 'PROVIDER_NOT_FOUND'; END IF; INSERT INTO wallets (provider_id, balance) VALUES (p_provider_id, 0) ON CONFLICT (provider_id) DO NOTHING; INSERT INTO subscriptions (provider_id, next_due_date) VALUES (p_provider_id, v_provider.subscription_start_date) ON CONFLICT (provider_id) DO NOTHING; INSERT INTO approval_history (subject_type, subject_id, action, performed_by) VALUES ('PROVIDER', p_provider_id, 'APPROVE', p_admin_id); INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'APPROVAL', 'Application approved', 'Your provider account is now active.' FROM provider_profiles WHERE id = p_provider_id; INSERT INTO admin_actions (admin_id, action, target_type, target_id) VALUES (p_admin_id, 'APPROVE_PROVIDER', 'provider_profiles', p_provider_id); RETURN v_provider; END; $$;

CREATE OR REPLACE FUNCTION reject_provider(p_provider_id uuid, p_admin_id uuid, p_reason text) RETURNS provider_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_provider provider_profiles; v_is_admin boolean; BEGIN SELECT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') INTO v_is_admin; IF NOT v_is_admin THEN RAISE EXCEPTION 'ONLY_ADMINISTRATORS_CAN_REJECT'; END IF; UPDATE provider_profiles SET status = 'REJECTED', updated_at = now() WHERE id = p_provider_id RETURNING * INTO v_provider; IF v_provider.id IS NULL THEN RAISE EXCEPTION 'PROVIDER_NOT_FOUND'; END IF; INSERT INTO approval_history (subject_type, subject_id, action, reason, performed_by) VALUES ('PROVIDER', p_provider_id, 'REJECT', p_reason, p_admin_id); INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'REJECTION', 'Application rejected', p_reason FROM provider_profiles WHERE id = p_provider_id; INSERT INTO admin_actions (admin_id, action, target_type, target_id, details) VALUES (p_admin_id, 'REJECT_PROVIDER', 'provider_profiles', p_provider_id, jsonb_build_object('reason', p_reason)); RETURN v_provider; END; $$;

CREATE OR REPLACE FUNCTION request_correction_provider(p_provider_id uuid, p_admin_id uuid, p_reason text) RETURNS provider_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_provider provider_profiles; v_is_admin boolean; BEGIN SELECT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') INTO v_is_admin; IF NOT v_is_admin THEN RAISE EXCEPTION 'ONLY_ADMINISTRATORS_CAN_REQUEST_CORRECTION'; END IF; UPDATE provider_profiles SET status = 'REJECTED', updated_at = now() WHERE id = p_provider_id RETURNING * INTO v_provider; IF v_provider.id IS NULL THEN RAISE EXCEPTION 'PROVIDER_NOT_FOUND'; END IF; INSERT INTO approval_history (subject_type, subject_id, action, reason, performed_by) VALUES ('PROVIDER', p_provider_id, 'REQUEST_CORRECTION', p_reason, p_admin_id); INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'CORRECTION_REQUIRED', 'Correction requested', 'Please update your submission: ' || p_reason FROM provider_profiles WHERE id = p_provider_id; INSERT INTO admin_actions (admin_id, action, target_type, target_id, details) VALUES (p_admin_id, 'REQUEST_CORRECTION', 'provider_profiles', p_provider_id, jsonb_build_object('reason', p_reason)); RETURN v_provider; END; $$;

CREATE OR REPLACE FUNCTION suspend_provider(p_provider_id uuid, p_admin_id uuid, p_reason text DEFAULT null) RETURNS provider_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_provider provider_profiles; v_is_admin boolean; BEGIN SELECT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') INTO v_is_admin; IF NOT v_is_admin THEN RAISE EXCEPTION 'ONLY_ADMINISTRATORS_CAN_SUSPEND'; END IF; UPDATE provider_profiles SET status = 'SUSPENDED', updated_at = now() WHERE id = p_provider_id RETURNING * INTO v_provider; IF v_provider.id IS NULL THEN RAISE EXCEPTION 'PROVIDER_NOT_FOUND'; END IF; UPDATE vehicles SET is_available = false WHERE provider_id = p_provider_id AND status = 'APPROVED'; INSERT INTO approval_history (subject_type, subject_id, action, reason, performed_by) VALUES ('PROVIDER', p_provider_id, 'SUSPEND', p_reason, p_admin_id); INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'PROVIDER_INACTIVE', 'Account suspended', coalesce(p_reason, 'Your provider account has been suspended.') FROM provider_profiles WHERE id = p_provider_id; INSERT INTO admin_actions (admin_id, action, target_type, target_id, details) VALUES (p_admin_id, 'SUSPEND_PROVIDER', 'provider_profiles', p_provider_id, jsonb_build_object('reason', p_reason)); RETURN v_provider; END; $$;

CREATE OR REPLACE FUNCTION unsuspend_provider(p_provider_id uuid, p_admin_id uuid) RETURNS provider_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_provider provider_profiles; v_is_admin boolean; BEGIN SELECT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') INTO v_is_admin; IF NOT v_is_admin THEN RAISE EXCEPTION 'ONLY_ADMINISTRATORS_CAN_UNSUSPEND'; END IF; UPDATE provider_profiles SET status = 'APPROVED', updated_at = now() WHERE id = p_provider_id RETURNING * INTO v_provider; IF v_provider.id IS NULL THEN RAISE EXCEPTION 'PROVIDER_NOT_FOUND'; END IF; UPDATE vehicles SET is_available = true WHERE provider_id = p_provider_id AND status = 'APPROVED'; INSERT INTO approval_history (subject_type, subject_id, action, performed_by) VALUES ('PROVIDER', p_provider_id, 'APPROVE', p_admin_id); INSERT INTO notifications (user_id, type, title, body) SELECT user_id, 'APPROVAL', 'Account reactivated', 'Your provider account has been reactivated.' FROM provider_profiles WHERE id = p_provider_id; INSERT INTO admin_actions (admin_id, action, target_type, target_id) VALUES (p_admin_id, 'UNSUSPEND_PROVIDER', 'provider_profiles', p_provider_id); RETURN v_provider; END; $$;

CREATE OR REPLACE FUNCTION create_order_secure(p_user_id uuid, p_provider_id uuid, p_items jsonb, p_total_amount numeric, p_currency text, p_note text DEFAULT null) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_order_id uuid; v_item jsonb; BEGIN IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'p_items must be non-empty'; END IF; INSERT INTO orders (id, user_id, provider_id, status, total_amount, currency, requires_payment_proof, created_at) VALUES (gen_random_uuid(), p_user_id, p_provider_id, 'CREATED', p_total_amount, coalesce(p_currency, 'ETB'), true, now()) RETURNING id INTO v_order_id; FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP INSERT INTO order_items (id, order_id, product_id, quantity, unit_price) VALUES (gen_random_uuid(), v_order_id, (v_item->>'product_id')::uuid, (v_item->>'quantity')::int, (v_item->>'unit_price')::numeric); END LOOP; INSERT INTO order_status_history (id, order_id, from_status, to_status, changed_by, note) VALUES (gen_random_uuid(), v_order_id, null, 'CREATED', p_user_id, p_note); RETURN (SELECT to_jsonb(o) FROM orders o WHERE o.id = v_order_id); END; $$;
REVOKE EXECUTE ON FUNCTION create_order_secure(uuid, uuid, jsonb, numeric, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION create_order_secure(uuid, uuid, jsonb, numeric, text, text) TO service_role;

CREATE OR REPLACE FUNCTION mark_notification_read(p_notification_id uuid) RETURNS notifications LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_notification notifications; BEGIN UPDATE notifications SET is_read = true WHERE id = p_notification_id AND user_id = auth.uid() RETURNING * INTO v_notification; IF v_notification.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; RETURN v_notification; END; $$;
CREATE OR REPLACE FUNCTION mark_all_notifications_read() RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_count int; BEGIN UPDATE notifications SET is_read = true WHERE user_id = auth.uid() AND is_read = false; GET DIAGNOSTICS v_count = row_count; RETURN v_count; END; $$;
CREATE OR REPLACE FUNCTION upsert_notification_preferences(p_push_enabled boolean DEFAULT null, p_in_app_enabled boolean DEFAULT null) RETURNS notification_preferences LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_prefs notification_preferences; BEGIN INSERT INTO notification_preferences (user_id, push_enabled, in_app_enabled) VALUES (auth.uid(), coalesce(p_push_enabled, true), coalesce(p_in_app_enabled, true)) ON CONFLICT (user_id) DO UPDATE SET push_enabled = coalesce(p_push_enabled, notification_preferences.push_enabled), in_app_enabled = coalesce(p_in_app_enabled, notification_preferences.in_app_enabled) RETURNING * INTO v_prefs; RETURN v_prefs; END; $$;
CREATE OR REPLACE FUNCTION create_n8n_event(p_event_type text, p_entity_type text, p_entity_id uuid DEFAULT null, p_payload jsonb DEFAULT null) RETURNS n8n_events LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_event n8n_events; BEGIN INSERT INTO n8n_events (event_type, entity_type, entity_id, payload) VALUES (p_event_type, p_entity_type, p_entity_id, p_payload) RETURNING * INTO v_event; RETURN v_event; END; $$;

CREATE OR REPLACE FUNCTION approve_wallet_recharge(p_recharge_id uuid, p_admin_id uuid) RETURNS wallet_recharge_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_recharge wallet_recharge_requests; v_wallet wallets; v_txn wallet_transactions; BEGIN IF NOT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO v_recharge FROM wallet_recharge_requests WHERE id = p_recharge_id FOR UPDATE; IF v_recharge.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF v_recharge.status = 'APPROVED' THEN RETURN v_recharge; END IF; IF v_recharge.status != 'PENDING' THEN RAISE EXCEPTION 'NOT_PENDING'; END IF; SELECT * INTO v_wallet FROM wallets WHERE id = v_recharge.wallet_id FOR UPDATE; IF v_wallet.id IS NULL THEN RAISE EXCEPTION 'WALLET_NOT_FOUND'; END IF; UPDATE wallets SET balance = balance + v_recharge.amount, updated_at = now() WHERE id = v_wallet.id RETURNING * INTO v_wallet; INSERT INTO wallet_transactions (wallet_id, provider_id, transaction_type, gross_amount, platform_fee, net_amount, balance_after, status, idempotency_key) VALUES (v_wallet.id, v_recharge.provider_id, 'RECHARGE', v_recharge.amount, 0, v_recharge.amount, v_wallet.balance, 'COMPLETED', 'recharge:' || v_recharge.id::text) RETURNING * INTO v_txn; UPDATE wallet_recharge_requests SET status = 'APPROVED', approved_by = p_admin_id, approved_at = now(), updated_at = now() WHERE id = p_recharge_id RETURNING * INTO v_recharge; INSERT INTO notifications (user_id, type, title, body) SELECT pp.user_id, 'APPROVAL', 'Recharge Approved', v_recharge.amount::text || ' ETB credited' FROM provider_profiles pp WHERE pp.id = v_recharge.provider_id; INSERT INTO audit_logs (actor_id, event_type, entity_type, entity_id, metadata) VALUES (p_admin_id, 'WALLET_RECHARGE_APPROVED', 'wallets', v_wallet.id, jsonb_build_object('recharge_id', p_recharge_id, 'amount', v_recharge.amount)); RETURN v_recharge; END; $$;

CREATE OR REPLACE FUNCTION reject_wallet_recharge(p_recharge_id uuid, p_admin_id uuid, p_reason text) RETURNS wallet_recharge_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_recharge wallet_recharge_requests; BEGIN IF NOT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO v_recharge FROM wallet_recharge_requests WHERE id = p_recharge_id FOR UPDATE; IF v_recharge.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF v_recharge.status != 'PENDING' THEN RAISE EXCEPTION 'NOT_PENDING'; END IF; UPDATE wallet_recharge_requests SET status = 'REJECTED', rejection_reason = p_reason, approved_by = p_admin_id, approved_at = now(), updated_at = now() WHERE id = p_recharge_id RETURNING * INTO v_recharge; INSERT INTO notifications (user_id, type, title, body) SELECT pp.user_id, 'REJECTION', 'Recharge Rejected', 'Reason: ' || p_reason FROM provider_profiles pp WHERE pp.id = v_recharge.provider_id; INSERT INTO audit_logs (actor_id, event_type, entity_type, entity_id, metadata) VALUES (p_admin_id, 'WALLET_RECHARGE_REJECTED', 'wallets', v_recharge.wallet_id, jsonb_build_object('recharge_id', p_recharge_id, 'reason', p_reason)); RETURN v_recharge; END; $$;

CREATE OR REPLACE FUNCTION admin_cash_recharge(p_provider_id uuid, p_amount numeric, p_reason text, p_admin_id uuid) RETURNS wallets LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_wallet wallets; v_balance_before numeric; BEGIN IF NOT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF p_amount <= 0 THEN RAISE EXCEPTION 'AMOUNT_MUST_BE_POSITIVE'; END IF; SELECT * INTO v_wallet FROM wallets WHERE provider_id = p_provider_id FOR UPDATE; IF v_wallet.id IS NULL THEN RAISE EXCEPTION 'WALLET_NOT_FOUND'; END IF; v_balance_before := v_wallet.balance; UPDATE wallets SET balance = balance + p_amount, updated_at = now() WHERE id = v_wallet.id RETURNING * INTO v_wallet; INSERT INTO wallet_transactions (wallet_id, provider_id, transaction_type, gross_amount, platform_fee, net_amount, balance_after, status, idempotency_key) VALUES (v_wallet.id, p_provider_id, 'ADMIN_CASH', p_amount, 0, p_amount, v_wallet.balance, 'COMPLETED', 'admin-cash:' || p_provider_id::text || ':' || now()::text); INSERT INTO admin_wallet_actions (admin_id, provider_id, wallet_id, action_type, amount, reason, balance_before, balance_after) VALUES (p_admin_id, p_provider_id, v_wallet.id, 'CASH_RECHARGE', p_amount, p_reason, v_balance_before, v_wallet.balance); INSERT INTO notifications (user_id, type, title, body) SELECT pp.user_id, 'APPROVAL', 'Cash Recharge', p_amount::text || ' ETB credited' FROM provider_profiles pp WHERE pp.id = p_provider_id; INSERT INTO audit_logs (actor_id, event_type, entity_type, entity_id, metadata) VALUES (p_admin_id, 'ADMIN_CASH_RECHARGE', 'wallets', v_wallet.id, jsonb_build_object('provider_id', p_provider_id, 'amount', p_amount)); RETURN v_wallet; END; $$;

CREATE OR REPLACE FUNCTION admin_wallet_adjustment(p_provider_id uuid, p_amount numeric, p_reason text, p_admin_id uuid) RETURNS wallets LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_wallet wallets; v_balance_before numeric; v_action_type text; BEGIN IF NOT exists (SELECT 1 FROM user_roles WHERE user_id = p_admin_id AND role = 'ADMIN') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF p_amount = 0 THEN RAISE EXCEPTION 'AMOUNT_CANNOT_BE_ZERO'; END IF; SELECT * INTO v_wallet FROM wallets WHERE provider_id = p_provider_id FOR UPDATE; IF v_wallet.id IS NULL THEN RAISE EXCEPTION 'WALLET_NOT_FOUND'; END IF; v_balance_before := v_wallet.balance; IF p_amount > 0 THEN v_action_type := 'ADJUSTMENT_CREDIT'; ELSE v_action_type := 'ADJUSTMENT_DEBIT'; END IF; IF p_amount < 0 AND v_wallet.balance + p_amount < 0 THEN IF NOT get_setting_bool('allow_negative_wallet') THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE'; END IF; END IF; UPDATE wallets SET balance = balance + p_amount, updated_at = now() WHERE id = v_wallet.id RETURNING * INTO v_wallet; INSERT INTO wallet_transactions (wallet_id, provider_id, transaction_type, gross_amount, platform_fee, net_amount, balance_after, status, idempotency_key) VALUES (v_wallet.id, p_provider_id, 'ADJUSTMENT', abs(p_amount), 0, abs(p_amount), v_wallet.balance, 'COMPLETED', 'adjustment:' || p_provider_id::text || ':' || now()::text); INSERT INTO admin_wallet_actions (admin_id, provider_id, wallet_id, action_type, amount, reason, balance_before, balance_after) VALUES (p_admin_id, p_provider_id, v_wallet.id, v_action_type, abs(p_amount), p_reason, v_balance_before, v_wallet.balance); INSERT INTO notifications (user_id, type, title, body) SELECT pp.user_id, 'ADMIN_MESSAGE', 'Wallet Adjustment', 'Adjusted by ' || p_amount::text || ' ETB' FROM provider_profiles pp WHERE pp.id = p_provider_id; INSERT INTO audit_logs (actor_id, event_type, entity_type, entity_id, metadata) VALUES (p_admin_id, 'ADMIN_WALLET_ADJUSTMENT', 'wallets', v_wallet.id, jsonb_build_object('provider_id', p_provider_id, 'amount', p_amount)); RETURN v_wallet; END; $$;

CREATE OR REPLACE FUNCTION find_nearby_drivers(p_lat double precision, p_lng double precision, p_radius_km numeric DEFAULT 10, p_vehicle_category_id uuid DEFAULT null) RETURNS TABLE (provider_id uuid, vehicle_id uuid, provider_name text, vehicle_brand text, vehicle_model text, vehicle_plate text, distance_km numeric, vehicle_category uuid) LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public AS $$ DECLARE v_location geography(Point,4326); BEGIN v_location := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography; RETURN QUERY SELECT ds.provider_id, v.id, coalesce(pp.business_name, pr.full_name), v.brand, v.model, v.plate_number, ROUND((ST_Distance(ds.current_location, v_location) / 1000.0)::numeric, 2), v.category_id FROM driver_status ds JOIN provider_profiles pp ON pp.id = ds.provider_id AND pp.status = 'APPROVED' JOIN profiles pr ON pr.id = pp.user_id JOIN vehicles v ON v.provider_id = ds.provider_id AND v.is_available = true AND v.status = 'APPROVED' WHERE ds.is_online = true AND ds.current_location IS NOT NULL AND ds.current_ride_id IS NULL AND ST_DWithin(ds.current_location, v_location, p_radius_km * 1000) AND (p_vehicle_category_id IS NULL OR v.category_id = p_vehicle_category_id) ORDER BY ST_Distance(ds.current_location, v_location) LIMIT 20; END; $$;

CREATE OR REPLACE FUNCTION update_driver_location(p_provider_id uuid, p_lat double precision, p_lng double precision) RETURNS driver_status LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_status driver_status; BEGIN IF NOT exists (SELECT 1 FROM provider_profiles WHERE id = p_provider_id AND user_id = auth.uid()) THEN RAISE EXCEPTION 'NOT_YOUR_STATUS'; END IF; INSERT INTO driver_status (provider_id, current_location, last_location_update, updated_at) VALUES (p_provider_id, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography, now(), now()) ON CONFLICT (provider_id) DO UPDATE SET current_location = ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography, last_location_update = now(), updated_at = now() RETURNING * INTO v_status; RETURN v_status; END; $$;

CREATE OR REPLACE FUNCTION set_driver_online(p_provider_id uuid, p_online boolean, p_lat double precision DEFAULT null, p_lng double precision DEFAULT null) RETURNS driver_status LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_status driver_status; BEGIN IF NOT exists (SELECT 1 FROM provider_profiles WHERE id = p_provider_id AND user_id = auth.uid() AND status = 'APPROVED') THEN RAISE EXCEPTION 'NOT_APPROVED'; END IF; IF p_online AND (p_lat IS NULL OR p_lng IS NULL) THEN RAISE EXCEPTION 'LOCATION_REQUIRED'; END IF; INSERT INTO driver_status (provider_id, is_online, current_location, last_location_update, updated_at) VALUES (p_provider_id, p_online, CASE WHEN p_online THEN ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography ELSE null END, CASE WHEN p_online THEN now() ELSE null END, now()) ON CONFLICT (provider_id) DO UPDATE SET is_online = p_online, current_location = CASE WHEN p_online THEN ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography ELSE driver_status.current_location END, last_location_update = CASE WHEN p_online THEN now() ELSE driver_status.last_location_update END, updated_at = now() RETURNING * INTO v_status; RETURN v_status; END; $$;

CREATE OR REPLACE FUNCTION create_ride_request(p_user_id uuid, p_pickup_lat double precision, p_pickup_lng double precision, p_destination_lat double precision, p_destination_lng double precision, p_pickup_text text DEFAULT null, p_destination_text text DEFAULT null, p_vehicle_category_id uuid DEFAULT null) RETURNS ride_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_ride ride_requests; BEGIN IF p_user_id != auth.uid() THEN RAISE EXCEPTION 'CANNOT_CREATE_FOR_ANOTHER_USER'; END IF; INSERT INTO ride_requests (user_id, pickup_location, destination_location, pickup_text, destination_text, vehicle_category_id, status) VALUES (p_user_id, ST_SetSRID(ST_MakePoint(p_pickup_lng, p_pickup_lat), 4326)::geography, ST_SetSRID(ST_MakePoint(p_destination_lng, p_destination_lat), 4326)::geography, p_pickup_text, p_destination_text, p_vehicle_category_id, 'REQUESTED') RETURNING * INTO v_ride; INSERT INTO ride_status_history (ride_request_id, from_status, to_status, changed_by) VALUES (v_ride.id, null, 'REQUESTED', p_user_id); RETURN v_ride; END; $$;

CREATE OR REPLACE FUNCTION update_vehicle_location(p_vehicle_id uuid, p_lat double precision, p_lng double precision) RETURNS vehicles LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_vehicle vehicles; BEGIN IF NOT exists (SELECT 1 FROM vehicles v WHERE v.id = p_vehicle_id AND owns_provider_profile(v.provider_id)) THEN RAISE EXCEPTION 'NOT_OWNED'; END IF; UPDATE vehicles SET current_location = ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography WHERE id = p_vehicle_id RETURNING * INTO v_vehicle; RETURN v_vehicle; END; $$;

CREATE OR REPLACE FUNCTION handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, full_name, phone, email, status) VALUES (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', 'New User'), new.phone, new.email, 'PENDING_APPROVAL'::account_status) ON CONFLICT (id) DO NOTHING; INSERT INTO public.user_roles (user_id, role) VALUES (new.id, 'USER'::app_role) ON CONFLICT (user_id, role) DO NOTHING; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION handle_new_provider_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.user_roles (user_id, role) VALUES (new.user_id, new.provider_type::app_role) ON CONFLICT (user_id, role) DO NOTHING; INSERT INTO public.approval_requests (subject_type, subject_id, status) VALUES ('PROVIDER', new.id, 'PENDING_APPROVAL'::account_status) ON CONFLICT DO NOTHING; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION auto_create_user_approval_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO approval_requests (subject_type, subject_id, status) VALUES ('USER', NEW.id, 'PENDING_APPROVAL'); RETURN NEW; END; $$;

CREATE OR REPLACE FUNCTION auto_create_driver_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF new.status = 'APPROVED' AND new.provider_type = 'VEHICLE_PROVIDER' THEN INSERT INTO driver_status (provider_id, is_online) VALUES (new.id, false) ON CONFLICT (provider_id) DO NOTHING; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION auto_create_driver_status_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF new.status = 'APPROVED' AND new.provider_type = 'VEHICLE_PROVIDER' THEN INSERT INTO driver_status (provider_id, is_online) VALUES (new.id, false) ON CONFLICT (provider_id) DO NOTHING; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_provider_self_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != old.status THEN RAISE EXCEPTION 'STATUS_CANNOT_BE_SELF_MODIFIED'; END IF; IF new.provider_type != old.provider_type THEN RAISE EXCEPTION 'PROVIDER_TYPE_CANNOT_BE_MODIFIED'; END IF; IF new.subscription_start_date != old.subscription_start_date THEN RAISE EXCEPTION 'SUBSCRIPTION_DATES_ARE_SERVER_MANAGED'; END IF; IF old.owner_national_id IS NOT NULL AND new.owner_national_id != old.owner_national_id THEN RAISE EXCEPTION 'NATIONAL_ID_CANNOT_BE_CHANGED'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_profile_self_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != old.status THEN RAISE EXCEPTION 'PROFILE_STATUS_CANNOT_BE_SELF_MODIFIED'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_notification_injection() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() AND NOT pg_catalog.current_setting('role', true) = 'service_role' THEN RAISE EXCEPTION 'NOTIFICATIONS_CANNOT_BE_CREATED_BY_CLIENTS'; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_support_ticket_status_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF TG_OP = 'INSERT' AND new.status != 'OPEN' THEN RAISE EXCEPTION 'NEW_TICKETS_MUST_START_AS_OPEN'; END IF; IF TG_OP = 'UPDATE' AND new.status != old.status AND new.status != 'CLOSED' THEN RAISE EXCEPTION 'USERS_CAN_ONLY_CLOSE'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_payment_agreement_unaccept() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF old.accepted = true AND new.accepted = false THEN RAISE EXCEPTION 'CANNOT_UNACCEPT'; END IF; IF new.accepted = true AND (old.accepted = false OR old.accepted IS NULL) THEN new.accepted_at := now(); END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_vehicle_insert_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != 'PENDING_APPROVAL' THEN RAISE EXCEPTION 'MUST_START_AS_PENDING'; END IF; IF new.is_available != false THEN RAISE EXCEPTION 'NEW_VEHICLES_NOT_AVAILABLE'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_product_insert_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN new.rating := 0; new.review_count := 0; new.sales_count := 0; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_review_insert_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.user_id != auth.uid() THEN RAISE EXCEPTION 'CANNOT_CREATE_FOR_ANOTHER_USER'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_order_insert_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != 'CREATED' THEN RAISE EXCEPTION 'ORDERS_MUST_START_AS_CREATED'; END IF; IF new.user_id != auth.uid() THEN RAISE EXCEPTION 'CANNOT_CREATE_FOR_ANOTHER_USER'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_ride_insert_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != 'REQUESTED' THEN RAISE EXCEPTION 'MUST_START_AS_REQUESTED'; END IF; IF new.user_id != auth.uid() THEN RAISE EXCEPTION 'CANNOT_CREATE_FOR_ANOTHER_USER'; END IF; IF new.claimed_by_provider_id IS NOT NULL THEN RAISE EXCEPTION 'CLAIM_FIELDS_CANNOT_BE_SET'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_provider_insert_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != 'PENDING_APPROVAL' THEN RAISE EXCEPTION 'MUST_START_AS_PENDING'; END IF; IF new.user_id != auth.uid() THEN RAISE EXCEPTION 'CANNOT_CREATE_FOR_ANOTHER_USER'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_profile_insert_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != 'PENDING_APPROVAL' THEN RAISE EXCEPTION 'MUST_START_AS_PENDING'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_vehicle_self_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != old.status THEN RAISE EXCEPTION 'VEHICLE_STATUS_CANNOT_BE_SELF_MODIFIED'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_payment_proof_self_verification() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.verification_status != old.verification_status THEN RAISE EXCEPTION 'VERIFICATION_IS_ADMIN_ONLY'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_order_self_privilege_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != old.status THEN RAISE EXCEPTION 'ORDER_STATUS_CHANGE_REQUIRES_SERVER_FUNCTION'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_subscription_self_modification() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.status != old.status THEN RAISE EXCEPTION 'SUBSCRIPTION_STATUS_CANNOT_BE_SELF_MODIFIED'; END IF; IF new.next_due_date != old.next_due_date THEN RAISE EXCEPTION 'SUBSCRIPTION_DATES_CANNOT_BE_SELF_MODIFIED'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_role_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN RAISE EXCEPTION 'ROLE_ASSIGNMENT_IS_ADMIN_ONLY'; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_wallet_direct_balance_edit() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF new.balance != old.balance THEN RAISE EXCEPTION 'BALANCE_MODIFICATION_REQUIRES_SECURE_FUNCTION'; END IF; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_system_settings_self_modification() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN RAISE EXCEPTION 'SETTINGS_ARE_ADMIN_ONLY'; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_audit_log_deletion() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN RAISE EXCEPTION 'AUDIT_LOGS_CANNOT_BE_DELETED'; RETURN null; END; $$;

CREATE OR REPLACE FUNCTION prevent_wallet_txn_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN IF old.status = 'COMPLETED' AND NOT is_admin() THEN RAISE EXCEPTION 'COMPLETED_TRANSACTIONS_CANNOT_BE_MODIFIED'; END IF; RETURN new; END; $$;

CREATE OR REPLACE FUNCTION prevent_approval_history_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY_DEFINER SET search_path = public AS $$ BEGIN RAISE EXCEPTION 'APPROVAL_HISTORY_IS_IMMUTABLE'; RETURN null; END; $$;

CREATE OR REPLACE FUNCTION prevent_inactive_provider_publish() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF NEW.listing_status = 'ACTIVE' AND OLD.listing_status != 'ACTIVE' THEN IF NOT exists (SELECT 1 FROM provider_profiles pp WHERE pp.id = NEW.provider_id AND pp.status = 'APPROVED') THEN RAISE EXCEPTION 'SUSPENDED_PROVIDERS_CANNOT_PUBLISH'; END IF; END IF; END IF; RETURN NEW; END; $$;

CREATE OR REPLACE FUNCTION prevent_inactive_provider_publish_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin() THEN IF NEW.listing_status = 'ACTIVE' THEN IF NOT exists (SELECT 1 FROM provider_profiles pp WHERE pp.id = NEW.provider_id AND pp.status = 'APPROVED') THEN RAISE EXCEPTION 'SUSPENDED_PROVIDERS_CANNOT_PUBLISH'; END IF; END IF; END IF; RETURN NEW; END; $$;

CREATE OR REPLACE FUNCTION update_product_rating() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE v_target uuid; BEGIN IF tg_op = 'DELETE' THEN IF old.target_type = 'PRODUCT' THEN v_target := old.target_id; END IF; ELSE IF new.target_type = 'PRODUCT' THEN v_target := new.target_id; END IF; IF tg_op = 'UPDATE' AND old.target_type = 'PRODUCT' AND old.target_id IS DISTINCT FROM new.target_id THEN UPDATE products p SET rating = coalesce((SELECT avg(rating) FROM reviews r WHERE r.target_type = 'PRODUCT' AND r.target_id = old.target_id), 0), review_count = (SELECT count(*) FROM reviews r WHERE r.target_type = 'PRODUCT' AND r.target_id = old.target_id) WHERE p.id = old.target_id; END IF; END IF; IF v_target IS NOT NULL THEN UPDATE products p SET rating = coalesce((SELECT avg(rating) FROM reviews r WHERE r.target_type = 'PRODUCT' AND r.target_id = v_target), 0), review_count = (SELECT count(*) FROM reviews r WHERE r.target_type = 'PRODUCT' AND r.target_id = v_target) WHERE p.id = v_target; END IF; RETURN null; END; $$;

CREATE OR REPLACE FUNCTION sync_store_listing_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF TG_OP = 'INSERT' THEN UPDATE provider_stores SET listing_count = (SELECT COUNT(*) FROM products WHERE provider_id = NEW.provider_id AND is_active = true AND listing_status = 'ACTIVE') WHERE provider_id = NEW.provider_id; RETURN NEW; ELSIF TG_OP = 'DELETE' THEN UPDATE provider_stores SET listing_count = (SELECT COUNT(*) FROM products WHERE provider_id = OLD.provider_id AND is_active = true AND listing_status = 'ACTIVE') WHERE provider_id = OLD.provider_id; RETURN OLD; END IF; RETURN NULL; END; $$;

CREATE OR REPLACE FUNCTION sync_store_listing_count_on_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.listing_status IS DISTINCT FROM OLD.listing_status THEN UPDATE provider_stores SET listing_count = (SELECT COUNT(*) FROM products WHERE provider_id = NEW.provider_id AND is_active = true AND listing_status = 'ACTIVE') WHERE provider_id = NEW.provider_id; END IF; RETURN NEW; END; $$;

